<?php
declare(strict_types=1);
require_once __DIR__.'/TicketServiceViews.php';

function ticket_header(string $active,string $title):void
{
    $portal=Auth::user()['role_portal']??'employee';render_portal_header(in_array($portal,['hr','admin'],true)?$portal:'employee',$active,$title);
    echo '<link rel="stylesheet" href="public/assets/tickets.css?v=20261020-15">';
}
function ticket_error_page(string $message):void
{
    ticket_header('hr-requests-my','HR Concerns');echo '<div class="alert error">'.e($message).'</div><a class="btn" href="'.e(url(Auth::landingPage())).'">Back to workspace</a>';render_portal_footer();
}
function ticket_status(string $status,string $type='PAYROLL_CONCERN'):string
{
    return '<span class="badge '.match($status){'COMPLETED'=>'green','REJECTED','CANCELLED'=>'red','RETURNED'=>'amber',default=>'gray'}.'">'.e(TicketTypes::label($status,$type)).'</span>';
}
function ticket_upload_input(string $id):void
{ ?>
    <div class="field"><label for="<?=e($id)?>">Supporting attachments (optional)</label><input id="<?=e($id)?>" type="file" name="attachments[]" accept=".pdf,.jpg,.jpeg,.png,.webp" multiple><small>PDF, JPG, PNG or WEBP. Up to five files per request, 10 MB each.</small></div>
<?php }
function ticket_new_page(array $employee,array $types,string $key,array $old):void
{
    $selected=(int)($old['ticket_type_id']??$_GET['type']??0);
    foreach($types as $type)if((int)$type['id']===$selected && $type['code']!=='PAYROLL_CONCERN'){ticket_service_new($employee,$types,$type,$key,$old);return;}
    ticket_header('hr-requests-my','File an HR Request');
    page_head('Employee Self-Service / HR Concerns','File an HR Request','<a class="btn" href="'.url('hr-requests-my').'">My HR requests</a>');
    // $types is already limited to the role's ticket.file.<type> permissions; the server re-checks on save.
    if(!in_array('PAYROLL_CONCERN',array_column($types,'code'),true)){
        echo '<section class="panel ticket-panel"><div class="panel-body">';
        if($types){ticket_service_select($types,0);}else echo '<p>Your role has no HR request types assigned. Please ask HR.</p>';
        echo '</div></section>';render_portal_footer();return;
    }
    $q=db()->prepare('SELECT COALESCE(ds.name,d.name,b.name) FROM employees e LEFT JOIN directory_sections ds ON ds.id=e.directory_section_id LEFT JOIN departments d ON d.id=e.department_id LEFT JOIN branches b ON b.id=e.branch_id WHERE e.id=?');$q->execute([$employee['id']]);$section=$q->fetchColumn(); ?>
    <form method="post" enctype="multipart/form-data" class="panel ticket-panel"><?=csrf_field()?><input type="hidden" name="action" value="core_ticket_create"><input type="hidden" name="submission_key" value="<?=e($key)?>">
      <div class="panel-body"><div class="field"><label for="ticket-type">Request type</label><select id="ticket-type" name="ticket_type_id" onchange="location.href='index.php?page=hr-request-new&type='+this.value" required><option value="">Choose a type</option><?php foreach($types as $type):?><option value="<?=(int)$type['id']?>" <?=($selected===(int)$type['id'])?'selected':''?>><?=e($type['name'])?></option><?php endforeach;?></select></div>
      <div class="ticket-facts"><div><span>Employee Code</span><strong><?=e($employee['employee_no'])?></strong></div><div><span>Name</span><strong><?=e($employee['first_name'].' '.$employee['last_name'])?></strong></div><div><span>Branch / Section</span><strong><?=e($employee['branch_name'].' / '.$section)?></strong></div><div><span>Company</span><strong><?=e($employee['company_group'].' · '.$employee['company_name'])?></strong></div></div>
      <div class="field"><label for="concern-date">Date</label><input type="date" name="concern_date" id="concern-date" max="<?=date('Y-m-d')?>" value="<?=e($old['concern_date']??date('Y-m-d'))?>" required><small>One cutoff per request. For another cutoff, file a separate request. Closed cutoffs and late filings go directly to HR for a later-period review.</small></div>
      <div class="field"><label for="concern-explanation">Remarks / Explanation</label><textarea id="concern-explanation" name="explanation" rows="5" maxlength="5000" required><?=e($old['explanation']??'')?></textarea></div>
      <?php ticket_upload_input('new-attachments');?><div class="ticket-actions"><button class="btn" name="intent" value="DRAFT">Save draft</button><button class="btn primary" name="intent" value="SUBMIT">Submit HR request</button></div></div>
    </form>
    <?php render_portal_footer();
}
function ticket_list_page(string $mode,array $result,array $filters):void
{
    if(in_array($mode,['services','accounting','feed'],true)){ticket_service_list($result,$filters,$mode);return;}
    $page=match($mode){'hr'=>'hr-payroll-concerns','inbox'=>'hr-request-inbox','team'=>'hr-request-team',default=>'hr-requests-my'};
    $title=match($mode){'hr'=>'Payroll Concern Queue','inbox'=>'HR Request Inbox','team'=>'Team Requests (view only)',default=>'My HR Requests'};ticket_header($page,$title);
    page_head('HR Concerns',$title,$mode!=='team'&&(Auth::can('tickets.request_self')||Auth::can('ticket.file_for_others'))?'<a class="btn primary" href="'.url('hr-request-new').'">File an HR request</a>':'');
    if($mode==='team'):?><p class="ticket-note">Requests from the branches, areas and people you oversee. You can read them but not approve, comment or attach files. Incident Reports are never shown here.</p><?php endif;
    if($mode==='my'):?><p class="ticket-note">HR concerns appear here. Your existing <a href="<?=url('employee-requests')?>">Payroll &amp; Timekeeping requests</a> keep their own list.</p><?php endif;
    if($mode==='hr'): ?>
    <form method="get" class="panel ticket-panel"><input type="hidden" name="page" value="hr-payroll-concerns"><div class="panel-body ticket-filters">
      <div class="field"><label for="queue-status">Status</label><select id="queue-status" name="status"><option value="">All statuses</option><?php foreach(array_keys(TicketPolicy::TRANSITIONS) as $status):if($status==='DRAFT')continue;?><option value="<?=e($status)?>" <?=($filters['status']??'')===$status?'selected':''?>><?=e(stage_label($status))?></option><?php endforeach;?></select></div>
      <div class="field"><label for="queue-company">Company Name</label><select id="queue-company" name="business_unit_id"><option value="0">All companies</option><?php foreach(FoundationRepository::businessUnits() as $row):?><option value="<?=(int)$row['id']?>" <?=(int)($filters['business_unit_id']??0)===(int)$row['id']?'selected':''?>><?=e($row['name'])?></option><?php endforeach;?></select></div>
      <div class="field"><label for="queue-branch">Branch</label><select id="queue-branch" name="branch_id"><option value="0">All branches</option><?php foreach(FoundationRepository::branches() as $row):?><option value="<?=(int)$row['id']?>" <?=(int)($filters['branch_id']??0)===(int)$row['id']?'selected':''?>><?=e($row['name'])?></option><?php endforeach;?></select></div>
      <div class="field"><label for="queue-period">Period</label><select id="queue-period" name="payroll_period_id"><option value="0">All periods</option><?php foreach(db()->query('SELECT id,code FROM payroll_cutoffs ORDER BY period_start DESC') as $row):?><option value="<?=(int)$row['id']?>" <?=(int)($filters['payroll_period_id']??0)===(int)$row['id']?'selected':''?>><?=e($row['code'])?></option><?php endforeach;?></select></div><button class="btn">Filter queue</button>
    </div></form><?php endif;?>
    <section class="panel ticket-scroll"><table class="tbl ticket-table"><thead><tr><th>HR request</th><th>Employee / Company</th><th><?=$mode==='hr'?'Date / Cutoff':'Filed / Relevant date'?></th><th>Status</th><th></th></tr></thead><tbody>
      <?php foreach($result['rows'] as $t):?><tr><td><strong><?=e($t['ticket_no'])?></strong><div>HR Concern · <?=e($t['type_name'])?></div></td><td><?=e($t['payload_json']?json_decode($t['payload_json'],true)['employee_name']??($t['first_name'].' '.$t['last_name']):$t['first_name'].' '.$t['last_name'])?><div><?=e($t['company_group_snapshot'].' · '.$t['company_name_snapshot'])?></div><small><?=e($t['branch_name'])?></small></td><td><?php if($t['type_code']==='PAYROLL_CONCERN'):?><?=e($t['concern_date'])?><div><?=e($t['period_start'].' to '.$t['period_end'])?></div><?php if($t['is_late']):?><span class="badge amber">Late · HR review</span><?php endif;else:?><?=e(substr($t['filed_at']??$t['created_at'],0,10))?><?php endif;?></td><td><?=ticket_status($t['status'],$t['type_code'])?></td><td><a class="btn sm" href="<?=url('hr-request',['id'=>$t['id']])?>">Open</a></td></tr><?php endforeach;
      if(!$result['rows']):?><tr><td colspan="5" class="empty">No HR requests in this list.</td></tr><?php endif;?></tbody></table></section>
    <nav aria-label="HR request pages"><p>Page <?=(int)$result['page']?> <?php if($result['page']>1):?><a class="btn" href="<?=e(url($page,array_replace($filters,['p'=>$result['page']-1])))?>">Previous</a><?php endif;if($result['has_next']):?><a class="btn" href="<?=e(url($page,array_replace($filters,['p'=>$result['page']+1])))?>">Next</a><?php endif;?></p></nav>
    <?php render_portal_footer();
}
function ticket_detail_page(array $t):void
{
    if($t['type_code']!=='PAYROLL_CONCERN'){ticket_service_detail($t);return;}
    $p=TicketService::permissions($t);$actionOld=$_SESSION['core_ticket_action'][$t['id']]??[];ticket_header('hr-requests-my',$t['ticket_no']);
    page_head('HR Concerns / '.$t['type_name'],$t['ticket_no'],'<a class="btn" href="'.url(TicketRepository::isHr()?'hr-payroll-concerns':(TicketRepository::canApprove()?'hr-request-inbox':'hr-requests-my')).'">Back to requests</a>'); ?>
    <div class="ticket-actions"><strong>HR Concern · <?=e($t['type_name'])?></strong><?=ticket_status($t['status'])?></div>
    <?php if($t['is_late']):?><div class="alert ticket-panel">Late concern: <?=e(stage_label($t['late_reason']))?>. HR will review it for a later open cutoff. Finalized attendance and payroll stay unchanged.</div><?php endif;?>
    <section class="panel ticket-panel"><div class="panel-body"><div class="ticket-facts"><div><span>Employee Code</span><strong><?=e($t['payload']['employee_code'])?></strong></div><div><span>Name</span><strong><?=e($t['payload']['employee_name'])?></strong></div><div><span>Branch / Section</span><strong><?=e(($t['payload']['branch_name']??$t['branch_name']).' / '.($t['payload']['section_name']??''))?></strong></div><div><span>Company</span><strong><?=e($t['company_group_snapshot'].' · '.$t['company_name_snapshot'])?></strong></div><div><span>Date</span><strong><?=e($t['concern_date'])?></strong></div><div><span>Cutoff</span><strong><?=e($t['period_start'].' to '.$t['period_end'])?></strong></div></div><h2>Remarks / Explanation</h2><p class="ticket-text"><?=e($t['payload']['explanation'])?></p></div></section>
    <?php if($p['edit']):$old=$_SESSION['core_ticket_edit'][$t['id']]??[];?>
    <form method="post" enctype="multipart/form-data" class="panel ticket-panel"><?=csrf_field()?><input type="hidden" name="action" value="core_ticket_edit"><input type="hidden" name="ticket_id" value="<?=(int)$t['id']?>"><input type="hidden" name="version" value="<?=(int)$t['version']?>"><input type="hidden" name="ticket_type_id" value="<?=(int)$t['ticket_type_id']?>"><div class="panel-body"><h2><?= $t['status']==='RETURNED'?'Revise returned request':'Edit draft'?></h2>
      <div class="field"><label for="edit-date">Concern date</label><input type="date" name="concern_date" id="edit-date" value="<?=e($old['concern_date']??$t['concern_date'])?>" max="<?=date('Y-m-d')?>" <?=$t['filed_at']?'readonly':''?> required></div>
      <div class="field"><label for="edit-explanation">Updated explanation</label><textarea name="explanation" id="edit-explanation" maxlength="5000" rows="5" required><?=e($old['explanation']??$t['payload']['explanation'])?></textarea></div><?php ticket_upload_input('edit-attachments');?><div class="ticket-actions"><button class="btn" name="intent" value="DRAFT">Save changes</button><button class="btn primary" name="intent" value="SUBMIT">Submit for review</button></div></div></form>
    <?php endif;?>
    <section class="panel ticket-panel"><div class="panel-head"><h2>Approval chain</h2></div><ol class="panel-body ticket-chain"><?php foreach($t['steps'] as $s):?><li><strong><?=e($s['approver_type']==='HR'?'HR review':$s['approver_type'])?></strong> · <?=e($s['approver_name']?:($s['actor_name']?:'Authorized HR reviewer'))?> · <?=e(stage_label($s['status']))?><?php if($s['remarks']):?><p class="ticket-text"><?=e($s['remarks'])?></p><?php endif;?></li><?php endforeach;if(!$t['steps']):?><li>The approval chain is set when you submit.</li><?php endif;?></ol></section>
    <?php if($p['approve'] || $p['return_reject'] || $p['hr']):?>
    <form method="post" class="panel ticket-panel" data-ticket-decision><?=csrf_field()?><input type="hidden" name="action" value="core_ticket_act"><input type="hidden" name="ticket_id" value="<?=(int)$t['id']?>"><input type="hidden" name="version" value="<?=(int)$t['version']?>"><div class="panel-body"><h2>Review this request</h2>
      <div class="field"><label for="decision-remarks">Review remarks / HR outcome explanation</label><textarea name="remarks" id="decision-remarks" maxlength="5000" rows="4"><?=e($actionOld['remarks']??'')?></textarea><small>Required for return, rejection, or HR completion.</small></div>
      <?php if($p['hr']):$targets=TicketRepository::targetPeriods($t);?><div class="field"><label for="hr-outcome">HR outcome</label><select name="outcome" id="hr-outcome"><option value="">Choose an outcome</option><option value="NO_CHANGE" <?=($actionOld['outcome']??'')==='NO_CHANGE'?'selected':''?>>No change</option><option value="MANUAL_ADJUSTMENT" <?=($actionOld['outcome']??'')==='MANUAL_ADJUSTMENT'?'selected':''?>>Manual adjustment in next open cutoff</option></select></div>
      <div class="field"><label for="target-period">Next open cutoff (manual adjustment only)</label><select name="target_period_id" id="target-period"><option value="0">No adjustment cutoff selected</option><?php if($targets):$target=$targets[0];?><option value="<?=(int)$target['id']?>" <?=(int)($actionOld['target_period_id']??0)===(int)$target['id']?'selected':''?>><?=e($target['period_start'].' to '.$target['period_end'])?></option><?php endif;?></select><?php if(!$targets):?><small>No later open cutoff is available. Keep this request in progress until HR opens the next period.</small><?php endif;?></div><?php endif;?>
      <div class="ticket-actions"><?php if($p['approve']):?><button class="btn primary" name="decision" value="APPROVE">Approve and send to HR</button><?php endif;if($p['hr']):if($t['status']==='PENDING_HR'):?><button class="btn" name="decision" value="START">Start HR review</button><?php endif;?><button class="btn primary" name="decision" value="COMPLETE">Complete HR concern</button><?php endif;if($p['return_reject']):?><button class="btn" name="decision" value="RETURN">Return for changes</button><button class="btn" name="decision" value="REJECT">Reject request</button><?php endif;?></div></div></form>
    <?php endif;if($p['cancel']):?><form method="post" class="ticket-panel"><?=csrf_field()?><input type="hidden" name="action" value="core_ticket_act"><input type="hidden" name="ticket_id" value="<?=(int)$t['id']?>"><input type="hidden" name="version" value="<?=(int)$t['version']?>"><button class="btn" name="decision" value="CANCEL" onclick="return confirm('Cancel this HR request?')">Cancel HR request</button></form><?php endif;?>
    <?php if($t['outcome']):?><section class="panel ticket-panel"><div class="panel-body"><h2>HR outcome: <?=e(stage_label($t['outcome']))?></h2><p class="ticket-text"><?=e($t['outcome_note'])?></p><?php foreach($t['effects'] as $effect):$instruction=json_decode($effect['instruction_json'],true);?><p><strong>Manual processing instruction recorded</strong> · Target cutoff: <?=e($instruction['target_period_label']??'See HR outcome')?>. HR Payroll must process this instruction manually; no pay was calculated or changed.</p><?php endforeach;?></div></section><?php endif;?>
    <section class="panel ticket-panel"><div class="panel-body"><h2>Attachments</h2><?php foreach($t['attachments'] as $file):?><p><a href="<?=url('hr-request-attachment',['id'=>$file['id']])?>"><?=e($file['original_name'])?></a> · <?=number_format($file['file_size']/1024,1)?> KB</p><?php endforeach;if(!empty($t['viewer_only'])):?><p>Attachments are not shown with view-only access.</p><?php elseif(!$t['attachments']):?><p>No attachments.</p><?php endif;
      if($p['attach'] && !$p['edit']):?><form method="post" enctype="multipart/form-data"><?=csrf_field()?><input type="hidden" name="action" value="core_ticket_attach"><input type="hidden" name="ticket_id" value="<?=(int)$t['id']?>"><?php ticket_upload_input('detail-attachments');?><button class="btn">Add attachments</button></form><?php endif;?></div></section>
    <section class="panel ticket-panel"><div class="panel-body"><h2>Comments</h2><?php foreach($t['comments'] as $c):?><article class="ticket-comment"><strong><?=e($c['author_name'])?></strong> <small><?=e($c['created_at'])?></small><p class="ticket-text"><?=e($c['body'])?></p></article><?php endforeach;if(!empty($t['viewer_only'])):?><p class="ticket-note">View-only access: you can read this request but not act on it, comment or attach files.</p><?php else:?><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="core_ticket_comment"><input type="hidden" name="ticket_id" value="<?=(int)$t['id']?>"><div class="field"><label for="comment-body">Add a comment</label><textarea name="body" id="comment-body" maxlength="3000" rows="3" required><?=e($_SESSION['core_ticket_comment'][$t['id']]??'')?></textarea></div><button class="btn">Post comment</button></form><?php endif;?></div></section>
    <section class="panel ticket-panel"><div class="panel-body"><h2>Ticket history</h2><ol class="ticket-history"><?php foreach($t['events'] as $ev):?><li><strong><?=e(stage_label($ev['event_type']))?></strong> · <?=e($ev['actor_name'])?> · <?=e($ev['created_at'])?><?php if($ev['to_status']):?> · <?=e(stage_label($ev['to_status']))?><?php endif;?></li><?php endforeach;?></ol></div></section>
    <script>document.querySelector('[data-ticket-decision]')?.addEventListener('submit',event=>{const decision=event.submitter?.value;const remarks=event.target.querySelector('[name="remarks"]');remarks.required=['RETURN','REJECT','COMPLETE'].includes(decision);if(!event.target.checkValidity()){event.preventDefault();event.target.reportValidity();}});</script>
    <?php render_portal_footer();
}
